from flask import Flask, request, jsonify
import os
import sqlite3
from functools import lru_cache

app = Flask(__name__)

# Database setup
DATABASE = 'photos.db'
CACHE_SIZE = 128  # Adjust cache size as needed

def init_db():
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS photos (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT UNIQUE,
                    price REAL,
                    description TEXT,
                    photo_path TEXT
                )''')
    c.execute('''CREATE TABLE IF NOT EXISTS pending_photos (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT,
                    price REAL,
                    description TEXT,
                    photo_path TEXT
                )''')
    conn.commit()
    conn.close()

@app.route('/submit', methods=['POST'])
def submit_photo():
    if 'photo' not in request.files:
        return jsonify({'error': 'No photo provided'}), 400

    photo = request.files['photo']
    name = request.form.get('name')
    price = request.form.get('price')
    description = request.form.get('description', '')

    if not name or not price:
        return jsonify({'error': 'Name and price are required'}), 400

    # Save the photo
    photo_path = os.path.join('uploads', photo.filename)
    photo.save(photo_path)

    # Check if a photo with the same name already exists
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT * FROM photos WHERE name = ?', (name,))
    existing_photo = c.fetchone()

    if existing_photo:
        # Move the new photo to the pending_photos table
        c.execute('INSERT INTO pending_photos (name, price, description, photo_path) VALUES (?, ?, ?, ?)',
                  (name, price, description, photo_path))
        conn.commit()
        conn.close()

        return jsonify({'message': 'Photo submitted successfully. Awaiting admin approval.'})

    # Insert the new photo
    c.execute('INSERT INTO photos (name, price, description, photo_path) VALUES (?, ?, ?, ?)',
              (name, price, description, photo_path))
    conn.commit()
    conn.close()

    return jsonify({'message': 'Photo submitted successfully'})

@app.route('/search', methods=['GET'])
def search_photos():
    query = request.args.get('query')
    if not query:
        return jsonify({'error': 'Search query is required'}), 400

    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT * FROM photos WHERE name LIKE ? OR description LIKE ?',
              (f'%{query}%', f'%{query}%'))
    results = c.fetchall()
    conn.close()

    return jsonify(results)

@lru_cache(maxsize=CACHE_SIZE)
def get_photos(page, page_size):
    offset = (page - 1) * page_size
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT * FROM photos ORDER BY price ASC, name ASC, description ASC LIMIT ? OFFSET ?',
              (page_size, offset))
    results = c.fetchall()
    conn.close()

    # Format the results to include photo URLs
    formatted_results = []
    for row in results:
        formatted_results.append({
            'id': row[0],
            'name': row[1],
            'price': row[2],
            'description': row[3],
            'photo_url': f'/uploads/{os.path.basename(row[4])}'
        })

    return formatted_results

@app.route('/list', methods=['GET'])
def list_photos():
    page = int(request.args.get('page', 1))
    page_size = int(request.args.get('page_size', 10))

    photos = get_photos(page, page_size)

    return jsonify(photos)

@app.route('/admin/pending', methods=['GET'])
def list_pending_photos():
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT * FROM pending_photos')
    results = c.fetchall()
    conn.close()

    # Format the results to include photo URLs
    formatted_results = []
    for row in results:
        formatted_results.append({
            'id': row[0],
            'name': row[1],
            'price': row[2],
            'description': row[3],
            'photo_url': f'/uploads/{os.path.basename(row[4])}'
        })

    return jsonify(formatted_results)

@app.route('/admin/approve', methods=['POST'])
def approve_photo():
    photo_id = request.form.get('photo_id')
    if not photo_id:
        return jsonify({'error': 'Photo ID is required'}), 400

    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()

    # Get the pending photo details
    c.execute('SELECT * FROM pending_photos WHERE id = ?', (photo_id,))
    pending_photo = c.fetchone()

    if not pending_photo:
        return jsonify({'error': 'Photo not found'}), 404

    name = pending_photo[1]

    # Check if a photo with the same name already exists
    c.execute('SELECT * FROM photos WHERE name = ?', (name,))
    existing_photo = c.fetchone()

    if existing_photo:
        # Delete the existing photo
        os.remove(existing_photo[4])
        c.execute('DELETE FROM photos WHERE id = ?', (existing_photo[0],))

    # Insert the new photo
    c.execute('INSERT INTO photos (name, price, description, photo_path) VALUES (?, ?, ?, ?)',
              (pending_photo[1], pending_photo[2], pending_photo[3], pending_photo[4]))

    # Delete the pending photo
    os.remove(pending_photo[4])
    c.execute('DELETE FROM pending_photos WHERE id = ?', (photo_id,))

    conn.commit()
    conn.close()

    # Clear the cache
    get_photos.cache_clear()

    return jsonify({'message': 'Photo approved and added successfully'})

@app.route('/admin/reject', methods=['POST'])
def reject_photo():
    photo_id = request.form.get('photo_id')
    if not photo_id:
        return jsonify({'error': 'Photo ID is required'}), 400

    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()

    # Get the pending photo details
    c.execute('SELECT * FROM pending_photos WHERE id = ?', (photo_id,))
    pending_photo = c.fetchone()

    if not pending_photo:
        return jsonify({'error': 'Photo not found'}), 404

    # Delete the pending photo
    os.remove(pending_photo[4])
    c.execute('DELETE FROM pending_photos WHERE id = ?', (photo_id,))

    conn.commit()
    conn.close()

    return jsonify({'message': 'Photo rejected and removed'})

