### Updated Python Function

```python
class Result:
    def __init__(self, value):
        self.value = value

    def is_ok(self):
        return isinstance(self, Ok)

    def is_err(self):
        return isinstance(self, Err)

    def unwrap(self):
        if self.is_ok():
            return self.value
        else:
            raise ValueError(f"Called 'unwrap' on an 'Err' value: {self.value}")

    def unwrap_or(self, default):
        return self.value if self.is_ok() else default

    def map(self, func):
        if self.is_ok():
            return Ok(func(self.value))
        else:
            return self

    def map_err(self, func):
        if self.is_err():
            return Err(func(self.value))
        else:
            return self

    def ok_or(self, err_value):
        if self.is_ok():
            return self
        else:
            return Err(err_value)


class Ok(Result):
    def __repr__(self):
        return f"Ok({self.value})"


class Err(Result):
    def __repr__(self):
        return f"Err({self.value})"


def get_sym_json_path(args, region_json):
    """
    Get the JSON paths for the given regions.

    :param args: A dictionary containing the 'region' key with a list of regions.
    :param region_json: A dictionary containing the '_Regions_' key with a mapping of regions to JSON paths.
    :return: A Result object containing a list of JSON paths if successful, or an error message if any region is not found.
    """
    regions = args.get('region', [])

    # Preprocess the region_json to ensure all keys are in uppercase
    upper_regions = {k.upper(): v for k, v in region_json['_Regions_'].items()}

    # Use map to transform each region into a Result
    results = [
        (upper_regions.get(region.upper(), None), region)
        for region in regions
    ]

    # Convert each result to a Result object using ok_or and map
    results = [
        Ok(upper_regions.get(region.upper(), None)).map(lambda x: x.to_string()).ok_or(f"{region} not found in _Regions_")
        for json_path, region in results
    ]

    # Collect the results into a single Result
    sym_json_path = collect(results)

    return sym_json_path

# Example usage
